import csv,subprocess,datetime as dt,decimal,collections
V="./vendor/bin/fxq"
def rate(p,d,s):
    out=subprocess.run([V,"rate",p,d,"--src",str(s)],capture_output=True,text=True).stdout.split()
    return decimal.Decimal(out[2])
txs=[r for r in csv.reader(l for l in open("fixtures/transactions.csv") if not l.startswith("#"))][1:]
stmt={(r[0],r[1]):(int(r[2]),int(r[3])) for r in list(csv.reader(l for l in open("fixtures/partner-statement.csv") if not l.startswith("#")))[1:] if r}
pairs={"USD":"USDKRW","EUR":"EURKRW","JPY":"JPYKRW","CNY":"CNYKRW"}
units={"JPY":100}
agg=collections.defaultdict(list)
for t in txs:
    a=dt.datetime.fromisoformat(t[2].replace("Z","+00:00"))+dt.timedelta(hours=9)
    d=a.date().isoformat()
    agg[(d,t[1],t[3])].append(decimal.Decimal(t[4]) * (-1 if t[5]=="REFUND" else 1))
for d in ["2026-10-01","2026-10-02","2026-10-03","2026-10-04","2026-10-05"]:
